solution.code:
declare const userBrand: unique symbol;
declare const orderBrand: unique symbol;
type UserId = string & { readonly [userBrand]: true };
type OrderId = string & { readonly [orderBrand]: true };
function openUser(id: UserId) { return id; }
function toOrderId(value: string): OrderId { return value as OrderId; }
const order = toOrderId("o-15");
// openUser(order); // TypeScript correctly reports a type error
console.log(order);
